/bin/zsh -lc "cat > src/server/services/milestone-service.ts <<'EOF'
import { and, eq, isNull, inArray, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { assertCan } from \"@/lib/permissions\";
import { assertNotArchived } from \"@/lib/soft-delete\";
import { assertOrgScope } from \"@/lib/tenant\";
import { getDb, milestones, issues } from \"@/server/db\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import { actorEnvelope, projectResource, requireFound, NotFoundError } from \"./_support\";
import { toIsoTimestamp } from \"@/types/common\";
import type { OrgId, ProjectId, MilestoneId, IssueId, IsoTimestamp } from \"@/types/common\";
import type { Actor } from \"@/types/member\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";
import type { CreateMilestoneInput, UpdateMilestoneInput, CloseMilestoneInput } from \"@/schemas/milestone\";

function map(row: typeof milestones."'$inferSelect): Milestone {
  return { ...row, id: row.id as MilestoneId, orgId: row.orgId as OrgId, projectId: row.projectId as ProjectId, targetDate: row.targetDate as IsoTimestamp | null, closedAt: row.closedAt as IsoTimestamp | null, createdAt: row.createdAt as IsoTimestamp, updatedAt: row.updatedAt as IsoTimestamp };
}
export function findMilestone(orgId: OrgId, id: MilestoneId): Milestone | null {
  const row = getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).get();
  return row ? map(row) : null;
}
export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, id: MilestoneId): Milestone {
  const m = findMilestone(orgId, id);
  if (!m || m.projectId !== projectId) throw new NotFoundError("Milestone", id);
  if (m.closedAt !== null) throw new MilestoneStateError("closed");
  return m;
}
async function project(actor: Actor, orgId: OrgId, id: ProjectId, write: boolean) {
  const p = requireFound(await projectRepo.findProjectById(orgId, id), "Project", id);
  assertCan(actor, write ? "project:update" : "project:read", projectResource(p));
  if (write) assertNotArchived("Project", p.id, p);
  return p;
}
function all(orgId: OrgId, projectId: ProjectId): Milestone[] {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all().map(map);
}
function checkName(rows: Milestone[], name: string, except?: MilestoneId) {
  if (rows.some(m => m.id !== except && m.name.trim().toLowerCase() === name.trim().toLowerCase())) throw new MilestoneStateError("name_taken");
}
function checkCap(rows: Milestone[]) {
  if (rows.filter(m => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) throw new MilestoneStateError("too_many_open");
}
export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId); await project(actor, input.orgId, input.projectId, true);
  const db = getDb(); const stamp = toIsoTimestamp(new Date());
  const result = db.transaction(tx => {
    const rows = tx.select().from(milestones).where(and(eq(milestones.orgId, input.orgId), eq(milestones.projectId, input.projectId))).all().map(map);
    checkName(rows, input.name); checkCap(rows);
    return map(tx.insert(milestones).values({ id: newId(), orgId: input.orgId, projectId: input.projectId, name: input.name, targetDate: input.targetDate ?? null, closedAt: null, createdAt: stamp, updatedAt: stamp }).returning().get());
  });
  await emit("milestone.created", { ...actorEnvelope(actor), milestoneId: result.id, projectId: result.projectId }); return result;
}
export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId); const m = requireFound(findMilestone(input.orgId, input.milestoneId), "Milestone", input.milestoneId); await project(actor, input.orgId, m.projectId, true);
  return getDb().transaction(tx => {
    if (input.name !== undefined) checkName(tx.select().from(milestones).where(and(eq(milestones.orgId, input.orgId), eq(milestones.projectId, m.projectId))).all().map(map), input.name, m.id);
    return map(tx.update(milestones).set({ ...(input.name === undefined ? {} : { name: input.name }), ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }), updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, m.id))).returning().get());
  });
